import pandas as pd
from datetime import timedelta

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract high_ts from watermark (single row)
    high_ts = watermark["high_ts"].iloc[0]

    # Filter events that are strictly after the watermark
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # If no new events, return current snapshot
    if len(new_events) == 0:
        result = target_snapshot[["user_id", "email", "status", "status_ts"]].copy()
        return {"new_snapshot": result}

    # Sort events by user_id, then by event_ts, then by event_seq for deterministic processing
    new_events = new_events.sort_values(by=["user_id", "event_ts", "event_seq"]).reset_index(drop=True)

    # Convert target_snapshot to dict for easier updates
    # Key: user_id, Value: {email, status, status_ts}
    snapshot_dict = {}
    for _, row in target_snapshot.iterrows():
        snapshot_dict[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"]
        }

    # Process events sequentially per user
    for _, event in new_events.iterrows():
        user_id = event["user_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        email = event["email"]

        # Get current state or create new user record
        if user_id not in snapshot_dict:
            current_state = {
                "email": None,
                "status": None,
                "status_ts": None
            }
        else:
            current_state = snapshot_dict[user_id]

        if op == "U":
            # Update operation
            current_status = current_state["status"]
            current_status_ts = current_state["status_ts"]

            if current_status == "DELETED":
                # Check resurrection window: update is allowed only if
                # event_ts > status_ts + 7 days (strictly more than 7 days after deletion)
                seven_days_after = current_status_ts + timedelta(days=7)
                if event_ts > seven_days_after:
                    # Resurrection allowed
                    snapshot_dict[user_id] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": event_ts
                    }
                # else: deletion is sticky, discard the update
            else:
                # ACTIVE or new user: apply the update
                snapshot_dict[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }

        elif op == "D":
            # Delete operation: soft delete
            snapshot_dict[user_id] = {
                "email": current_state["email"],  # Preserve email
                "status": "DELETED",
                "status_ts": event_ts
            }

    # Convert back to DataFrame
    rows = []
    for user_id, state in snapshot_dict.items():
        rows.append({
            "user_id": user_id,
            "email": state["email"],
            "status": state["status"],
            "status_ts": state["status_ts"]
        })

    new_snapshot = pd.DataFrame(rows)

    # Ensure correct dtypes
    if len(new_snapshot) > 0:
        new_snapshot = new_snapshot.astype({
            "user_id": "int64",
            "email": "object",
            "status": "object",
            "status_ts": "datetime64[us]"
        })
    else:
        new_snapshot = pd.DataFrame(columns=["user_id", "email", "status", "status_ts"])
        new_snapshot = new_snapshot.astype({
            "user_id": "int64",
            "email": "object",
            "status": "object",
            "status_ts": "datetime64[us]"
        })

    return {"new_snapshot": new_snapshot}
